        display: flex;
        align-items: center;
        padding: 10px;
        background: rgba(30, 30, 35, 0.6);
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 8px;
        cursor: pointer;
        transition:
          background 0.2s,
          transform 0.2s;
