        color: var(--accent-gold);
        font-weight: bold;
        margin-bottom: 5px;
      }

      .wx-list-preview {
        font-size: 0.85em;
        color: var(--text-dim);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }

      .wx-chat-view {
        display: none;
        flex-direction: column;
        height: 100%;
        position: relative;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 8px;
        overflow: hidden;
      }

      .wx-chat-bg {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
