      .wx-back-btn:hover {
        color: var(--accent-gold);
      }

      .wx-chat-title {
        font-size: 1.15em;
        color: var(--text-main);
        font-weight: bold;
        cursor: pointer;
        flex-grow: 1;
        text-align: center;
        margin-right: 10px;
        transition: color 0.2s;
        text-shadow: 0 1px 2px #000;
