      .wx-chat-title:hover {
        color: var(--accent-mana);
      }

      .wx-api-btn {
        cursor: pointer;
        color: var(--text-dim);
        font-size: 1.2em;
        transition:
          color 0.2s,
          transform 0.2s;
      }

      .wx-api-btn:hover {
        color: var(--accent-mana);
        transform: rotate(90deg);
      }

      .wx-chat-messages {
        position: relative;
        z-index: 1;
        flex-grow: 1;
        padding: 15px;
        overflow-y: auto;
        display: flex;
        flex-direction: column;
        gap: 15px;
        scrollbar-width: thin;
        min-height: 0;
