      .wx-msg-left {
        align-self: flex-start;
      }

      .wx-msg-right {
        align-self: flex-end;
        align-items: flex-end;
      }

      .wx-msg-sender {
        font-size: 0.75em;
        color: rgba(255, 255, 255, 0.6);
        margin-bottom: 4px;
        padding: 0 5px;
        text-shadow: 0 1px 1px #000;
      }

      .wx-msg-bubble {
        padding: 10px 14px;
        border-radius: 8px;
        font-size: 0.9em;
        line-height: 1.5;
        word-wrap: break-word;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
        backdrop-filter: blur(2px);
        white-space: pre-wrap;
      }

      .wx-msg-left .wx-msg-bubble {
        background: rgba(30, 40, 50, 0.85);
        border: 1px solid rgba(77, 166, 255, 0.3);
        color: #e0f0ff;
        border-top-left-radius: 0;
      }

      .wx-msg-right .wx-msg-bubble {
        background: rgba(46, 204, 113, 0.25);
        border: 1px solid rgba(46, 204, 113, 0.4);
        color: #e0f0ff;
        border-top-right-radius: 0;
      }

      .wx-msg-actions {
        display: none;
        gap: 10px;
        margin-top: 4px;
        font-size: 0.75em;
        opacity: 0.8;
        justify-content: flex-end;
      }

      .wx-msg-left .wx-msg-actions {
        justify-content: flex-start;
      }

      .wx-msg-row:hover .wx-msg-actions {
        display: flex;
      }

      .wx-msg-action-btn {
        cursor: pointer;
        color: var(--text-dim);
        transition: color 0.2s;
        background: rgba(0, 0, 0, 0.3);
        padding: 2px 6px;
        border-radius: 4px;
        border: 1px solid rgba(255, 255, 255, 0.1);
      }

      .wx-msg-action-btn:hover {
        color: var(--accent-gold);
        border-color: var(--accent-gold);
        background: rgba(255, 215, 0, 0.1);
      }

      .wx-chat-input-area {
        position: relative;
        z-index: 105;
        padding: 12px;
        background: rgba(10, 10, 15, 0.9);
        border-top: 1px solid rgba(255, 255, 255, 0.1);
        flex-shrink: 0;
      }

      .wx-detail-modal {
        display: none;
        position: absolute;
        top: 45px;
        left: 50%;
        transform: translateX(-50%);
        background: linear-gradient(145deg,
            rgba(25, 25, 30, 0.95),
            rgba(15, 15, 20, 0.98));
        border: 1px solid var(--accent-mana);
        border-radius: 8px;
        padding: 15px;
        z-index: 100;
        box-shadow:
          0 5px 20px rgba(0, 0, 0, 0.6),
          inset 0 0 10px rgba(77, 166, 255, 0.1);
        width: 200px;
        text-align: center;
        backdrop-filter: blur(5px);
        animation: fadeIn 0.2s ease;
      }

      .wx-detail-modal.show {
        display: block;
      }

      .wx-detail-item {
        margin: 10px 0;
        font-size: 0.95em;
        display: flex;
        justify-content: space-between;
        border-bottom: 1px dashed rgba(255, 255, 255, 0.1);
        padding-bottom: 6px;
      }

      .wx-detail-item:last-child {
        border-bottom: none;
        margin-bottom: 0;
      }

      @media (max-width: 700px) {
        .terminal-container {
          border-radius: 0;
          border: none;
          border-top: 2px solid var(--border-metal);
          border-bottom: 2px solid var(--border-metal);
        }

        .content-grid {
          grid-template-columns: minmax(0, 1fr);
        }

        .main-panel,
        .tab-content,
        .info-card {
          min-width: 0;
          max-width: 100%;
        }

        .portrait-search-row {
          min-width: 0;
        }

        .portrait-search-row .reply-input {
          min-width: 50px;
          flex: 1 1 0;
        }

        .status-panel {
          flex-direction: row;
          padding: 15px;
          gap: 20px;
          flex-wrap: wrap;
          justify-content: center;
          background-color: rgba(20, 18, 22, 0.8);
          border-right: none;
          border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .avatar-frame {
